/**
 solid-name: TaskStatusPresentation
 solid-category: presentation
 solid-description: Maps a TaskListItem.status string to its visual representation (system image name + Color). Single source of truth for both the todo checklist (todoWrite tool) and the task panel (taskCreate/taskUpdate tools).
 */
enum TaskStatusPresentation {
    static func icon(for status: String) -> String {
        switch status {
        case "completed":   return "checkmark.circle.fill"
        case "in_progress": return "circle.dotted.circle"
        case "deleted":     return "xmark.circle"
        default:            return "circle"
        }
    }

    static func color(for status: String) -> Color {
        switch status {
        case "completed":   return .green
        case "in_progress": return .orange
        case "deleted":     return .red
        default:            return .secondary
        }
    }
}

