private extension Dictionary where Key == String, Value == String {
    /// Returns the dictionary as 'key: value' lines, sorted ascending by key, joined by newline.
    /// Used to render MCP tool inputs and generic 'other' tool argument blobs uniformly.
    var sortedKeyValueLines: String {
        sorted(by: { $0.key < $1.key })
            .map { "\($0.key): \($0.value)" }
            .joined(separator: "\n")
    }
}

