// New shared diff renderer
/**
 solid-name: DiffLine
 solid-category: model
 solid-description: One rendered diff line with its visual classification (added/removed). Used by DiffLinesView.
 */
struct DiffLine: Identifiable {
    let id = UUID()
    let sign: String
    let text: String
    let color: Color
    static func removed(_ line: String) -> DiffLine {
        DiffLine(sign: "- ", text: line, color: .red)
    }
    static func added(_ line: String) -> DiffLine {
        DiffLine(sign: "+ ", text: line, color: .green)
    }
}

/**
 solid-name: DiffLinesView
 solid-category: view-component
 solid-stack: [swiftui]
 solid-description: Renders a colored diff body for tool calls (Edit, Write). Falls back to ToolResultView when the line count exceeds a threshold. Pure view — no business logic.
 */
struct DiffLinesView: View {
    let filePath: String
    let lines: [DiffLine]
    let fallbackContent: String?
    let threshold: Int

    var body: some View {
        if lines.count > threshold, let fallback = fallbackContent {
            VStack(alignment: .leading, spacing: 4) {
                if !filePath.isEmpty { filePathLabel }
                ToolResultView(content: fallback)
            }
        } else {
            VStack(alignment: .leading, spacing: 0) {
                if !filePath.isEmpty {
                    filePathLabel.padding(.bottom, 4)
                }
                ForEach(lines) { line in
                    Text("\(line.sign)\(line.text)")
                        .font(.system(size: 10, design: .monospaced))
                        .foregroundStyle(line.color.opacity(0.9))
                        .frame(maxWidth: .infinity, alignment: .leading)
                        .padding(.horizontal, 4)
                        .padding(.vertical, 1)
                        .background(line.color.opacity(0.1))
                }
            }
            .textSelection(.enabled)
            .padding(4)
            .frame(maxWidth: .infinity, alignment: .leading)
            .background(Color.primary.opacity(0.04), in: RoundedRectangle(cornerRadius: 4))
        }
    }

    private var filePathLabel: some View {
        Text(filePath)
            .font(.system(size: 9, design: .monospaced))
            .foregroundStyle(.tertiary)
    }
}

// AFTER — editDiffView is now a thin assembler
private func editDiffView(_ d: EditToolData) -> some View {
    let oldLines = d.oldString.components(separatedBy: "\n").map(DiffLine.removed)
    let newLines = d.newString.components(separatedBy: "\n").map(DiffLine.added)
    let combined = (d.oldString.isEmpty ? [] : oldLines)
                 + (d.newString.isEmpty ? [] : newLines)
    let fallback = (d.oldString + (d.oldString.isEmpty ? "" : "\n") + d.newString)
    return DiffLinesView(filePath: d.filePath,
                         lines: combined,
                         fallbackContent: fallback,
                         threshold: 120)
}

private func writeDiffView(_ d: WriteToolData) -> some View {
    let lines = d.content.components(separatedBy: "\n").map(DiffLine.added)
    return DiffLinesView(filePath: d.filePath,
                         lines: lines,
                         fallbackContent: d.content,
                         threshold: 160)
}

