// New: Sources/LogMessageLoader.swift
/**
 solid-name: LogMessageLoading
 solid-category: abstraction
 solid-description: Loads parsed log messages from a URL with mtime-based caching. Hides file I/O and parsing strategy from the view-model.
 */
protocol LogMessageLoading: AnyObject {
    func loadMessages(from url: URL) async -> [LogMessage]
}

/**
 solid-name: LogMessageLoader
 solid-category: service
 solid-stack: [structured-concurrency]
 solid-description: Default LogMessageLoading implementation. Owns cached file mtime, the LogMessageParsing dependency, and the FileSystemProviding dependency. Detaches actual I/O+parse work onto a utility-priority task.
 */
actor LogMessageLoader: LogMessageLoading {
    private var lastMtime: Date?
    private let parser: LogMessageParsing
    private let fileSystem: FileSystemProviding

    init(parser: LogMessageParsing = LogParser(),
         fileSystem: FileSystemProviding = FileManager.default) {
        self.parser = parser
        self.fileSystem = fileSystem
    }

    func loadMessages(from url: URL) async -> [LogMessage] {
        let cached = lastMtime
        let fs = fileSystem
        let p = parser
        let (msgs, mtime): ([LogMessage], Date?) = await Task.detached(priority: .utility) {
            let attrs = try? fs.attributesOfItem(atPath: url.path)
            let mtime = attrs?[.modificationDate] as? Date
            if let cached, let mtime, cached == mtime { return ([], mtime) }
            return (p.parseMessages(at: url), mtime)
        }.value
        if let mtime { self.lastMtime = mtime }
        return msgs
    }
}

// New: Sources/LogDerivedStateBuilder.swift
struct LogDerivedState {
    let displayedMessages: [LogMessage]
    let taskList: [TaskListItem]
    let toolResultLookup: [String: String]
    let pendingPrompt: LogToolCall?
}

/**
 solid-name: LogDerivedStateBuilding
 solid-category: abstraction
 solid-description: Pure transformation from raw [LogMessage] into derived view state — filtered displayed messages, reconstructed task list, tool-result lookup, pending prompt detection.
 */
protocol LogDerivedStateBuilding {
    func build(from messages: [LogMessage]) -> LogDerivedState
}

/**
 solid-name: LogDerivedStateBuilder
 solid-category: service
 solid-description: Default LogDerivedStateBuilding implementation. Pure value-typed transformation — no dependencies, no side effects.
 */
struct LogDerivedStateBuilder: LogDerivedStateBuilding {
    func build(from messages: [LogMessage]) -> LogDerivedState {
        let displayed = messages.filter { !$0.textContent.isEmpty || !$0.toolCalls.isEmpty || $0.thinking != nil }
        var tasks: [TaskListItem] = []
        var nextId = 1
        var lookup: [String: String] = [:]
        var resolvedIDs: Set<String> = []
        for msg in messages {
            resolvedIDs.formUnion(msg.toolResultIDs)
            for (tid, content) in msg.toolResultContents { lookup[tid] = content }
            for tc in msg.toolCalls {
                switch tc.data {
                case .todoWrite(let d):
                    tasks = d.todos.enumerated().map { idx, item in
                        TaskListItem(id: "todo-\(idx)", content: item.content, status: item.status, activeForm: "")
                    }
                case .taskCreate(let d):
                    let id = "\(nextId)"; nextId += 1
                    tasks.append(TaskListItem(id: id, content: d.subject, status: "pending", activeForm: d.activeForm))
                case .taskUpdate(let d):
                    if let idx = tasks.firstIndex(where: { $0.id == d.taskId }), !d.status.isEmpty {
                        tasks[idx].status = d.status
                    }
                default: break
                }
            }
        }
        var prompt: LogToolCall?
        for msg in messages.reversed() where msg.role == .assistant {
            if let unresolved = msg.toolCalls.reversed().first(where: { !resolvedIDs.contains($0.id) && $0.data.needsPrompt }) {
                prompt = unresolved; break
            }
        }
        return LogDerivedState(displayedMessages: displayed, taskList: tasks, toolResultLookup: lookup, pendingPrompt: prompt)
    }
}

