@Observable
final class LogViewerViewModel: LogViewerData, LogViewerLocation, LogViewerActions {
    private(set) var messages: [LogMessage] = []
    private(set) var displayedMessages: [LogMessage] = []
    private(set) var isLoading = true
    private(set) var taskList: [TaskListItem] = []
    private(set) var toolResultLookup: [String: String] = [:]
    private(set) var pendingPrompt: LogToolCall?

    private let agent: AgentInfo
    private let target: LogTarget
    private let modelResolver: ModelResolving
    private let urlResolver: LogURLResolving
    private let messageLoader: LogMessageLoading
    private let derivedBuilder: LogDerivedStateBuilding
    private let pollScheduler: PollScheduling   // see fix-010 below — abstracts `poll(interval:)`

    init(agent: AgentInfo, target: LogTarget,
         modelResolver: ModelResolving = ClaudeModelAdapter(),
         urlResolver: LogURLResolving = LogURLResolver(),
         messageLoader: LogMessageLoading = LogMessageLoader(),
         derivedBuilder: LogDerivedStateBuilding = LogDerivedStateBuilder(),
         pollScheduler: PollScheduling = DefaultPollScheduler()) {
        self.agent = agent
        self.target = target
        self.modelResolver = modelResolver
        self.urlResolver = urlResolver
        self.messageLoader = messageLoader
        self.derivedBuilder = derivedBuilder
        self.pollScheduler = pollScheduler
    }

    var fileURL: URL { urlResolver.resolveURL(agent: agent, target: target) }

    func roleLabel(_ msg: LogMessage) -> String {
        switch msg.role {
        case .user: return "User"
        case .assistant:
            if let model = msg.model, !model.isEmpty {
                return modelResolver.resolve(modelID: model).displayName
            }
            return "Assistant"
        case .system: return "Hook"
        }
    }

    func loadMessages() async {
        let url = fileURL
        let msgs = await messageLoader.loadMessages(from: url)
        if !msgs.isEmpty {
            messages = msgs
            let derived = derivedBuilder.build(from: msgs)
            displayedMessages = derived.displayedMessages
            taskList = derived.taskList
            toolResultLookup = derived.toolResultLookup
            pendingPrompt = derived.pendingPrompt
        }
        isLoading = false
    }

    func startPolling() async {
        await pollScheduler.poll(interval: .seconds(2)) { [weak self] in
            await self?.loadMessages()
        }
    }
}

/**
 solid-name: PollScheduling
 solid-category: abstraction
 solid-stack: [structured-concurrency]
 solid-description: Repeatedly invokes an async closure on a fixed interval. Injected so view-models can be tested without real wall-clock waiting.
 */
protocol PollScheduling: Sendable {
    func poll(interval: Duration, _ tick: @escaping () async -> Void) async
}

struct DefaultPollScheduler: PollScheduling {
    func poll(interval: Duration, _ tick: @escaping () async -> Void) async {
        while !Task.isCancelled {
            await tick()
            try? await Task.sleep(for: interval)
        }
    }
}

